
@import 'material-symbols/outlined.css';

  :root{
    --navy:#041E42; --navy-2:#0A2A57; --blue:#1565D8; --blue-soft:#E8F0FD;
    --orange:#FF8C1A; --ice:#F2F6FC; --ink:#1C2A3A; --slate:#51607A;
    --line:#DCE5F2; --white:#FFF; --ok:#2ECC71;
    --disp:'Sora',sans-serif; --body:'IBM Plex Sans',sans-serif; --mono:'IBM Plex Mono',monospace;
  }
  *{margin:0;padding:0;box-sizing:border-box}
  /* Paragraphs fill their existing content column across all page components. */
  p{width:100%!important;max-width:100%!important;min-width:0}
  body{font-family:var(--body);color:var(--ink);background:#fff;line-height:1.6;-webkit-font-smoothing:antialiased}
  .site-progress{position:fixed;top:0;left:0;z-index:1000;width:0;height:3px;pointer-events:none;background:linear-gradient(90deg,var(--blue),var(--orange));box-shadow:0 0 12px rgba(21,101,216,.6);transition:width .08s linear}
  a{text-decoration:none;color:inherit}
  ul{list-style:none}
  .wrap{max-width:1240px;margin:0 auto;padding:0 24px}
  .draft-ribbon{position:fixed;top:14px;right:-44px;transform:rotate(45deg);background:var(--orange);color:#fff;font:600 11px/1 var(--mono);letter-spacing:.12em;padding:7px 50px;z-index:999;box-shadow:0 2px 8px rgba(4,30,66,.25)}

  /* Utility + promo */
  .utility{background:var(--navy);color:#B9C9E2;font-size:13px}
  .utility .wrap{display:flex;justify-content:space-between;align-items:center;min-height:36px;gap:16px;flex-wrap:wrap}
  .utility a{color:#B9C9E2}.utility a:hover{color:#fff}
  .utility .links{display:flex;gap:16px;flex-wrap:wrap}
  .utility .phone{font-family:var(--mono);font-size:12px;color:#fff}
  .promo{background:linear-gradient(90deg,var(--blue),#0E4CAB);color:#fff;text-align:center;font-size:13.5px;padding:8px 16px}
  .promo b{color:#FFD9AC}.promo .code{font-family:var(--mono);background:rgba(255,255,255,.15);padding:1px 8px;border-radius:4px}

  /* ===== NAV with full mega menus ===== */
  header.nav{position:sticky;top:0;background:#fff;border-bottom:1px solid var(--line);z-index:100}
  .nav .wrap{display:flex;align-items:center;justify-content:space-between;height:64px;gap:20px}
  .logo{font-family:var(--disp);font-weight:800;font-size:21px;color:var(--navy)}
  .logo span{color:var(--blue)}
  .logo .tag{display:block;font:500 9px/1 var(--mono);letter-spacing:.2em;color:var(--slate);margin-top:2px}
  nav.main{display:flex;height:64px}
  nav.main > .top{position:relative;display:flex;align-items:center}
  nav.main > .top > a{padding:0 15px;font-weight:500;font-size:14.5px;height:64px;display:flex;align-items:center;border-bottom:2.5px solid transparent}
  nav.main > .top:hover > a, nav.main > .top:focus-within > a{color:var(--blue);border-color:var(--blue)}
  nav.main > .top > a::after{content:"▾";font-size:9px;margin-left:5px;color:var(--slate)}
  .top.no-drop > a::after{content:""}
  .mega{position:fixed;left:0;right:0;top:auto;background:#fff;border-bottom:1px solid var(--line);box-shadow:0 24px 48px rgba(4,30,66,.14);opacity:0;visibility:hidden;transform:translateY(6px);transition:.18s;max-height:calc(100vh - 140px);overflow:auto}
  .top:hover .mega, .top:focus-within .mega{opacity:1;visibility:visible;transform:none}
  .mega-in{max-width:1240px;margin:0 auto;padding:30px 24px 34px;display:grid;gap:6px 34px}
  .cols-3{grid-template-columns:repeat(3,1fr)}
  .cols-4{grid-template-columns:repeat(4,1fr)}
  .cols-5{grid-template-columns:repeat(5,1fr)}
  .mcol h5{font:600 11px var(--mono);letter-spacing:.14em;text-transform:uppercase;color:var(--blue);border-bottom:1px solid var(--line);padding-bottom:8px;margin-bottom:10px}
  .mcol li{margin:0}
  .mcol a{display:block;font-size:13.5px;color:var(--ink);padding:4.5px 8px;border-radius:6px}
  .mcol a:hover{background:var(--blue-soft);color:var(--blue)}
  .mcol a small{display:block;font-size:11px;color:var(--slate)}
  .pill{font:600 9px var(--mono);letter-spacing:.06em;color:#B25400;background:#FFF0DE;border-radius:99px;padding:1px 7px;margin-left:6px;vertical-align:1px}
  .pill.b{color:var(--blue);background:var(--blue-soft)}
  .mcol{margin-bottom:14px}
  .btn{display:inline-block;font-weight:600;font-size:14px;padding:10px 20px;border-radius:8px;transition:.15s;border:1.5px solid transparent}
  .btn-primary{background:var(--orange);color:#fff}.btn-primary:hover{background:#E97A08}
  .btn-ghost{border-color:var(--line);color:var(--navy)}.btn-ghost:hover{border-color:var(--blue);color:var(--blue)}
  .nav-cta{display:flex;gap:10px}

  /* Hero + console */
  .hero{background:radial-gradient(1100px 560px at 85% -10%,#0E3A78 0%,var(--navy) 55%);color:#fff;padding:66px 0 78px}
  .hero .wrap{display:grid;grid-template-columns:1.05fr .95fr;gap:52px;align-items:center}
  .eyebrow{font:600 12px/1 var(--mono);letter-spacing:.2em;color:var(--orange);text-transform:uppercase;margin-bottom:16px}
  h1{font-family:var(--disp);font-weight:800;font-size:clamp(32px,4.4vw,48px);line-height:1.12;letter-spacing:-.02em;margin-bottom:18px}
  h1 em{font-style:normal;color:#7FB2FF}
  .hero p.lead{font-size:17px;color:#C7D5EC;max-width:52ch;margin-bottom:28px}
  .hero-ctas{display:flex;gap:12px;flex-wrap:wrap}
  #ppage.domain-whois-page :is(h1,h2,h3,h4,h5,h6,.pp-sec,.pp-uses b,.pp-why b){text-transform:capitalize}
  .hero .btn-ghost{border-color:rgba(255,255,255,.35);color:#fff}
  /* Homepage hero: four complete slides, each with its own copy and visual. */
  .home-hero-carousel{position:relative!important;display:block!important}
  .home-hero-slide{display:none;grid-template-columns:minmax(0,1fr);justify-items:center;align-items:center;text-align:center}
  .home-hero-slide.is-active{display:grid}
  .home-hero-slide h1{max-width:50ch;margin-bottom:10px;color:#fff;font-family:Georgia,'Times New Roman',serif;font-size:clamp(42px,4.5vw,45px);font-weight:700;line-height:1.01;letter-spacing:-.035em}
  .home-hero-slide h1 .shine{background:none;color:#ef955f;font-family:inherit;font-size:inherit;font-style:normal;font-weight:700;animation:none}
  .home-hero-copy{min-width:0}.home-hero-spotlight{position:static!important;display:inline!important;color:#ffb35b!important;font:700 13px/1.5 var(--body)!important;letter-spacing:0!important;white-space:normal!important;transform:none!important;opacity:1!important}
  .home-hero-copy{width:100%;max-width:1192px;margin-inline:auto}
  @media(min-width:1025px){.home-hero-slide h1{font-size:clamp(32px,3.4vw,45px);white-space:nowrap}}
  .home-hero-slide .hero-live{max-width:850px;margin-inline:auto}
  .home-hero-slide h1,.home-hero-slide p.lead{margin-inline:auto}
  .home-hero-slide .hero-ctas,.home-hero-slide .stat-line,.home-hero-slide .hero-live,.home-hero-slide .home-hero-dots,.home-hero-slide .rot-line{justify-content:center}
  .home-hero-slide .stat-line .sl{align-items:center}
  .home-hero-slide .home-hero-nvidia{display:flex;align-items:center;align-self:center;justify-content:center;flex:0 0 auto;max-width:100%;padding:6px 12px;background:#fff;border-radius:6px}
  .home-hero-slide .home-hero-nvidia img{display:block;width:179px;max-width:100%;height:auto;object-fit:contain}
  .hero .home-hero-slide .eyebrow::after{margin-inline:auto}
  .home-hero-dots{display:flex;align-items:center;gap:10px;margin-top:78px;margin-bottom: -50px;}
  .home-hero-slide .bare-metal-ctas{align-items:center}
  .home-hero-slide .performance-cloud-ctas{align-items:center}
  .home-hero-slide .performance-cloud-logos{display:flex;align-items:center;gap:12px;min-width:0}
  .home-hero-slide .performance-cloud-logo{display:block;width:100px;height:56px;padding:6px 10px;object-fit:contain;background:#fff;border-radius:8px;flex-shrink:0}
  @media(max-width:900px){
    .home-hero-slide .performance-cloud-ctas{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;max-width:440px;margin-inline:auto}
    .home-hero-slide .performance-cloud-logos{grid-row:1;justify-content:center;gap:8px}
    .home-hero-slide .performance-cloud-logos-left{grid-column:1}
    .home-hero-slide .performance-cloud-logos-right{grid-column:2}
    .home-hero-slide .performance-cloud-logo{width:calc((100% - 8px)/2);max-width:100px;height:50px;padding:6px}
    .home-hero-slide .performance-cloud-ctas .btn{width:100%;min-width:0;white-space:normal;text-align:center;grid-row:2}
  }
  .home-hero-slide .bare-metal-logo{display:block;box-sizing:border-box;width:100px;height:56px;padding:6px 10px;object-fit:contain;background:#fff;border-radius:8px;flex-shrink:0}
  @media(max-width:700px){.home-hero-slide .bare-metal-ctas{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;max-width:440px;margin-left:auto;margin-right:auto}.home-hero-slide .bare-metal-logo{width:100px;height:56px;justify-self:center;grid-row:1}.home-hero-slide .bare-metal-ryzen{grid-column:1}.home-hero-slide .bare-metal-intel{grid-column:2}.home-hero-slide .bare-metal-ctas .btn{width:100%;min-width:0;white-space:normal;box-sizing:border-box}}
  .home-hero-slide .gpu-server-ctas{align-items:center}
  .home-hero-slide .gpu-server-hero-image{display:block;box-sizing:border-box;height:64px;width:120px;padding:6px;object-fit:contain;background:#fff;border-radius:8px;flex-shrink:0}
  .home-hero-slide .gpu-server-card{width:150px}
  .home-hero-slide.is-cybird .hero-ctas{align-items:center}
  .home-hero-slide.is-cybird .cybird-made-in-india,
  .home-hero-slide.is-cybird .cybird-appliance{display:block;box-sizing:border-box;width:100px;height:56px;object-fit:contain;flex-shrink:0}
  .home-hero-slide.is-cybird .cybird-made-in-india{width:140px}
  .home-hero-slide.is-cybird .cybird-appliance{filter:drop-shadow(0 8px 10px rgba(0,0,0,.4))}
  .home-hero-slide.is-cybird .stat-line{margin-top:8px}
  .home-hero-slide.is-cybird .hero-live{margin-top:18px}
  .home-hero-slide.is-cybird .home-hero-dots{margin-top:24px}
  @media(max-width:700px){.home-hero-slide.is-cybird .hero-ctas{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;max-width:440px;margin-left:auto;margin-right:auto}.home-hero-slide.is-cybird .cybird-made-in-india{grid-column:1;grid-row:1;justify-self:center}.home-hero-slide.is-cybird .cybird-appliance{grid-column:2;grid-row:1;justify-self:center}.home-hero-slide.is-cybird .hero-ctas .btn{width:100%;min-width:0;white-space:normal;box-sizing:border-box}.home-hero-slide.is-cybird .hero-ctas .btn-primary{font-size:12px}}
  .home-hero-dots button{width:20px;height:7px;padding:0;border:0;border-radius:999px;background:rgba(151,172,206,.4);cursor:pointer;transition:width .24s ease,background .24s ease,box-shadow .24s ease}.home-hero-dots button:hover{background:rgba(203,222,248,.85)}.home-hero-dots button.is-active{width:46px;background:#1565D8;box-shadow:0 0 12px rgba(23, 87, 224, 0.8)}.home-hero-dots button:focus-visible{outline:2px solid #fff;outline-offset:px}
  @media(max-width:1024px){.home-hero-copy{padding-top:0}}
  @media(max-width:700px){.home-hero-slide .stat-line{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.home-hero-slide .hero-live{font-size:10px;white-space:normal}.home-hero-dots{margin-top:14px}}
  @media(max-width:480px){.home-hero-slide h1{font-size:clamp(32px,10vw,42px)}}

  .console{background:#06182F;border:1px solid #17395F;border-radius:14px;box-shadow:0 24px 60px rgba(0,0,0,.4);overflow:hidden}
  .console .bar{display:flex;align-items:center;gap:8px;padding:11px 16px;border-bottom:1px solid #17395F;font:500 11px var(--mono);color:#7E96B8;letter-spacing:.08em}
  .dot{width:9px;height:9px;border-radius:50%;background:var(--ok);position:relative}
  .dot::after{content:"";position:absolute;inset:-4px;border-radius:50%;border:1.5px solid var(--ok);opacity:.5;animation:pulse 2s infinite}
  @keyframes pulse{0%{transform:scale(.6);opacity:.7}100%{transform:scale(1.4);opacity:0}}
  @media (prefers-reduced-motion:reduce){.dot::after{animation:none}}
  .console table{width:100%;border-collapse:collapse;font-family:var(--mono);font-size:12.5px}
  .console td{padding:12px 16px;border-bottom:1px solid #10294A;color:#B9C9E2}
  .console td:last-child{text-align:right;color:#fff;font-weight:600}
  .console tr:last-child td{border-bottom:none}
  .ok{color:var(--ok)!important}
  .console .foot{padding:10px 16px;font:400 10.5px var(--mono);color:#5F7CA3;background:#051426}

  .trust{background:var(--ice);border-bottom:1px solid var(--line)}
  .trust .wrap{display:flex;justify-content:space-between;gap:18px;flex-wrap:wrap;padding:20px 24px}
  .trust .item{font-size:13px;color:var(--slate);display:flex;align-items:center;gap:7px;font-weight:500}
  .trust .item b{color:var(--navy);font-family:var(--mono)}
  .tick{width:15px;height:15px;border-radius:50%;background:var(--blue);color:#fff;display:inline-flex;align-items:center;justify-content:center;font-size:9px;flex:none}

  section{padding:20px 0 20px 0}
  .sec-head{max-width:680px;margin-bottom:42px}
  .sec-head .eyebrow{color:var(--blue)}
  h2{font-family:var(--disp);font-weight:700;font-size:clamp(25px,3vw,34px);color:var(--navy);letter-spacing:-.015em;line-height:1.2;margin-bottom:12px}
  .sec-head p{color:var(--slate);font-size:16px}

  /* Flagship products — expanded to 8 visible */
  .prod-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:18px}
  .flag-tabs{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));margin:0 0 28px;border:1px solid #BFD3F3;border-radius:14px;background:rgba(255,255,255,.86);box-shadow:0 12px 30px rgba(4,30,66,.07);overflow:hidden}
  .flag-tabs button{appearance:none;border:0;border-right:1px solid #D5E1F2;background:transparent;color:var(--slate);min-height:62px;padding:12px 16px;display:flex;align-items:center;justify-content:center;gap:10px;font:600 14px var(--disp);cursor:pointer;transition:background .22s,color .22s,box-shadow .22s}
  .flag-tabs button:last-child{border-right:0}
  .flag-tabs button:hover{background:var(--blue-soft);color:var(--blue)}
  .flag-tabs button:focus-visible{position:relative;z-index:2;outline:3px solid rgba(21,101,216,.28);outline-offset:-3px}
  .flag-tabs button.active{background:linear-gradient(135deg,var(--blue),#0C4EB1);color:#fff;box-shadow:0 10px 24px rgba(21,101,216,.24)}
  .prod-grid-tabbed{grid-template-columns:repeat(3,minmax(0,1fr));max-width:920px;margin:0 auto}
  .prod-grid-tabbed.smb-grid,.prod-grid-tabbed.infra-grid,.prod-grid-tabbed.protect-grid,.prod-grid-tabbed.productivity-grid{grid-template-columns:repeat(4,minmax(0,1fr));max-width:none}
  .card{border:1px solid var(--line);border-radius:14px;padding:24px 22px;background:#fff;transition:.18s;display:flex;flex-direction:column}
  .card:hover{border-color:var(--blue);box-shadow:0 14px 34px rgba(21,101,216,.12);transform:translateY(-3px)}
  .badge{position:absolute;top:24px;right:22px;max-width:calc(100% - 96px);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:600 10px var(--mono);letter-spacing:.1em;text-transform:uppercase;color:var(--blue);background:var(--blue-soft);padding:4px 10px;border-radius:99px}
  .badge.hot{color:#B25400;background:#FFF0DE}
  .card h3{font-family:var(--disp);font-size:17px;font-weight:600;color:var(--navy);margin-bottom:6px}
  .card p{display:-webkit-box;min-height:3.1em;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:2;font-size:13.5px;line-height:1.55;color:var(--slate);margin-bottom:10px}
  .price{font-family:var(--mono);font-size:12.5px;color:var(--slate);margin-bottom:18px;white-space:nowrap}
  .price b{font-size:18px;color:var(--navy)}
  .card .more{margin-top:auto;border-top:1px dashed var(--line);padding-top:12px;font-weight:600;font-size:13.5px;color:var(--blue)}

  /* Keep every flagship card row compact and vertically aligned. */
  #flagship .card h3{display:-webkit-box;min-height:2.8em;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:2}
  #flagship .card .price{min-height:24px;margin-bottom:0}
  #flagship .card .more{margin-top:0}

  /* ===== FULL SERVICE DIRECTORY — every product visible on page ===== */
  .directory{background:var(--ice)}
  .directory .sec-head{max-width:none}
  .directory .directory-summary{white-space:nowrap}
  @media(max-width:900px){.directory .directory-summary{white-space:normal}}
  .dir-cat{background:#fff;border:1px solid var(--line);border-radius:14px;padding:26px;margin-bottom:18px}
  .dir-cat > h3{font-family:var(--disp);font-size:19px;font-weight:700;color:var(--navy);margin-bottom:4px}
  .dir-cat > .sub{font-size:13.5px;color:var(--slate);margin-bottom:18px}
  .dir-cat > h3 .cnt{font:600 11px var(--mono);color:var(--blue);background:var(--blue-soft);border-radius:99px;padding:2px 10px;margin-left:10px;vertical-align:3px}
  .dir-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:4px 26px}
  .dir-grid h5{font:600 10.5px var(--mono);letter-spacing:.12em;text-transform:uppercase;color:var(--blue);margin:12px 0 6px;grid-column:auto}
  .dgroup{break-inside:avoid}
  .dgroup h5{margin-top:0}
  .dgroup li a{display:block;font-size:13px;color:var(--ink);padding:3.5px 6px;border-radius:5px;border-left:2px solid transparent}
  .dgroup li a:hover{background:var(--blue-soft);color:var(--blue);border-left-color:var(--blue)}

  .why-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
  .testimonials{background:#fff;padding:36px 0 36px 0}.testimonial-head{text-align:center;max-width:900px;margin:0 auto 30px}.testimonial-head h2{font-size:clamp(27px,3vw,36px);margin:0;color:var(--navy)}.testimonial-head h2 span{color:#e52b4f}.testimonial-head h2 strong{color:var(--blue)}.testimonial-head p{margin:12px 0 0;color:var(--slate);font-size:15px}.testimonial-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.testimonial-card{position:relative;padding:22px 24px 26px;text-align:center;border:1px solid #d6e3f2;border-radius:15px;background:#fff;box-shadow:0 8px 22px rgba(7,31,69,.06)}.testimonial-avatar{display:grid;place-items:center;width:52px;height:52px;margin:0 auto 12px;border-radius:50%;background:linear-gradient(135deg,#2460dd,#6544e9);color:#fff;font:700 17px var(--disp)}.testimonial-quote{position:absolute;top:0;right:0;width:54px;height:54px;border-radius:0 14px 0 35px;background:linear-gradient(135deg,#1c62d3,#104ca9);color:#fff;font:700 28px Georgia;padding-top:8px}.testimonial-card h3{margin:0;color:var(--navy);font-size:16px}.testimonial-card small{display:block;margin-top:4px;color:var(--slate);font-size:12px}.testimonial-stars{margin:16px 0;color:#ff8b1a;font-size:16px;letter-spacing:2px}.testimonial-card p{margin:0;color:var(--slate);font-size:13px;line-height:1.6}
  .why .k{font-family:var(--mono);font-weight:600;font-size:25px;color:var(--blue);margin-bottom:6px}
  .why-layout{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:58px;align-items:center}
  .why-badge{display:inline-flex;padding:6px 13px;border-radius:999px;background:linear-gradient(135deg,#2147bd,#36adf3);color:#fff;font:700 11px/1 var(--disp);text-transform:uppercase}
  .why-intro h2{margin:17px 0 12px;max-width:500px;font-size:clamp(31px,3.4vw,43px);line-height:1.08}
  .why-intro>p{max-width:470px;margin:0;color:var(--ink);font-size:16px;line-height:1.55}
  .why-stats{display:flex;gap:44px;margin:34px 0 28px}.why-stats b{display:block;color:#214bc2;font:700 31px/1 var(--mono)}.why-stats span{display:block;margin-top:7px;color:var(--ink);font-size:13px;white-space:nowrap}.why-intro>small{color:var(--slate);font-size:13px}
  .why-features{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.why-feature{min-height:190px;padding:20px;border:1px solid #dce4ee;border-radius:13px;background:#fff;box-shadow:0 7px 18px rgba(7,31,69,.09)}.why-feature-icon{display:grid;place-items:center;width:44px;height:44px;margin-bottom:17px;border-radius:8px;background:linear-gradient(135deg,#1a4fcb,#2aa8f0);color:#fff;font-size:24px}.why-feature h3{margin:0 0 8px;color:var(--navy);font-size:16px}.why-feature p{margin:0;color:var(--ink);font-size:13.5px;line-height:1.55}
  .quote{background:var(--navy);color:#fff}
  .quote blockquote{max-width:760px;margin:0 auto;text-align:center}
  .quote blockquote p{font-family:var(--disp);font-weight:500;font-size:clamp(18px,2.3vw,24px);line-height:1.5;margin-bottom:20px}
