/* Centred mouse-style Back to Top control. */
.back-to-top{position:fixed;left:50%;bottom:16px;z-index:120;width:42px;height:42px;border-radius:7px;
  border:1px solid rgba(255,255,255,.42);background:linear-gradient(155deg,#1485ff 0%,#075fd2 55%,#06489f 100%);color:#fff;
  display:flex;align-items:center;justify-content:center;padding:0;cursor:pointer;
  box-shadow:0 12px 30px rgba(5,82,176,.34),inset 0 1px 0 rgba(255,255,255,.3);
  opacity:0;visibility:hidden;pointer-events:none;transform:translate(-50%,14px) scale(.9);
  transition:opacity .22s,visibility .22s,transform .28s cubic-bezier(.2,.8,.2,1),box-shadow .22s}
.back-to-top::before{content:"";position:absolute;inset:-4px;border:1px solid rgba(20,133,255,.18);border-radius:10px;opacity:0;transform:scale(.9);transition:.25s}
.back-to-top.show{opacity:1;visibility:visible;pointer-events:auto;transform:translate(-50%,0) scale(1)}
.back-to-top:hover{transform:translate(-50%,-4px) scale(1.04);box-shadow:0 17px 38px rgba(5,82,176,.44),inset 0 1px 0 rgba(255,255,255,.32)}
.back-to-top:hover::before{opacity:1;transform:scale(1)}
.back-to-top-mouse{flex:0 0 auto;width:21px;height:29px;overflow:visible}
.back-to-top-wheel,.back-to-top-cue{animation:backToTopWheel 1.65s ease-in-out infinite}
@keyframes backToTopWheel{0%,100%{transform:translateY(3px);opacity:.45}45%{transform:translateY(-1px);opacity:1}}
.back-to-top:focus-visible{outline:3px solid var(--orange);outline-offset:3px}
@media(max-width:700px){
  .back-to-top{bottom:max(10px,env(safe-area-inset-bottom));width:40px;height:40px;padding:0;border-radius:7px}
  .back-to-top-mouse{width:20px;height:28px}
}
@media(prefers-reduced-motion:reduce){
  .back-to-top{transition:none}.back-to-top:hover{transform:translate(-50%,0)}
  .back-to-top-wheel,.back-to-top-cue{animation:none}
}

