/* Article page redesign */
.xh-blog-article{background:#fff}
.bp-bar-brand{display:flex;flex-direction:column;gap:2px}
.bp-bar-brand span{color:var(--navy);font:700 12px/1 var(--mono);letter-spacing:.12em;text-transform:uppercase}
.bp-bar-brand small{color:var(--slate);font:600 12px/1.4 var(--body)}
.bp-bar-link{color:var(--blue);font:700 13px/1.4 var(--body)}
.bp-bar-link:hover{text-decoration:underline}

.article-hero{background:
  radial-gradient(560px 280px at 95% 8%,rgba(21,101,216,.2),transparent 70%),
  linear-gradient(135deg,#071d3f 0%,#0b3471 56%,#1061c2 100%);
  padding:62px 0 56px}
.article-hero .wrap{display:grid;grid-template-columns:minmax(0,1fr) minmax(320px,.92fr);gap:34px;align-items:center;max-width:1240px}
.article-hero-copy{max-width:760px}
.article-hero h1{margin:18px 0 16px;color:#fff;font:800 clamp(34px,4.2vw,56px)/1.08 var(--disp);letter-spacing:-.04em}
.article-hero .lede{max-width:62ch;color:#d8e6fb;font-size:18px;line-height:1.75}
.article-author-row{display:flex;align-items:center;gap:14px;margin-top:28px}
.article-author-badge{display:grid;place-items:center;width:52px;height:52px;border-radius:50%;background:linear-gradient(135deg,#ffffff,#dbeafe);color:#0c4ea8;font:800 20px/1 var(--disp);box-shadow:0 10px 24px rgba(0,0,0,.16)}
.article-author-row b{display:block;color:#fff;font:700 15px/1.3 var(--body)}
.article-author-row span{display:block;margin-top:2px;color:#c6d8f5;font:500 13px/1.45 var(--body)}
.article-hero-media{position:relative}
.article-cover{margin:0;min-height:360px;border:1px solid rgba(255,255,255,.12);border-radius:28px;box-shadow:0 28px 64px rgba(2,12,29,.32)}

.article-main{background:linear-gradient(180deg,#f7faff 0%,#ffffff 20%)}
.article-grid{display:grid;grid-template-columns:290px minmax(0,1fr);gap:32px;padding:40px 24px 72px}
.article-sidebar{position:relative}
.article-side-card{position:sticky;top:94px;margin-bottom:18px;padding:22px;border:1px solid #d7e4f4;border-radius:22px;background:#fff;box-shadow:0 18px 40px rgba(5,38,84,.06)}
.article-sidebar .article-side-card + .article-side-card{top:auto;position:relative}
.article-side-kicker{display:inline-flex;margin-bottom:12px;padding:6px 10px;border-radius:999px;background:#e9f2ff;color:#0d57b6;font:700 10px/1 var(--mono);letter-spacing:.12em;text-transform:uppercase}
.article-side-card h3{margin:0 0 14px;color:var(--navy);font:760 21px/1.2 var(--disp)}
.article-side-card p{margin:0;color:var(--slate);font-size:14px;line-height:1.65}
.article-facts{display:grid;gap:14px;margin:0;padding:0;list-style:none}
.article-facts li{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding-bottom:14px;border-bottom:1px solid #ebf1f8}
.article-facts li:last-child{padding-bottom:0;border-bottom:0}
.article-facts span{color:#6b7f99;font:600 12px/1.4 var(--mono);letter-spacing:.03em;text-transform:uppercase}
.article-facts b{color:var(--navy);font:700 13px/1.45 var(--body);text-align:right}
.article-toc{display:grid;gap:8px}
.article-toc a{display:block;padding:11px 12px;border:1px solid #d9e5f3;border-radius:12px;background:#f8fbff;color:var(--ink);font:600 13px/1.45 var(--body);transition:border-color .2s,transform .2s,box-shadow .2s}
.article-toc a:hover{transform:translateY(-2px);border-color:#9ec1ef;box-shadow:0 10px 20px rgba(21,101,216,.08)}
.article-side-cta .row{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}

.article-content{min-width:0}
.article-body{max-width:100%;padding:0;margin:0;border-radius:28px}
.article-body>p:first-child{font-size:19px;line-height:1.85;color:#233449}
.article-body p{font-size:17px;line-height:1.9;color:#203144;margin:0 0 24px}
.article-body h2{scroll-margin-top:110px;position:relative;margin:46px 0 18px;padding-top:18px;color:var(--navy);font:780 clamp(28px,2.9vw,38px)/1.16 var(--disp);letter-spacing:-.03em;border-top:1px solid #dce6f3}
.article-body ul{display:grid;gap:14px;margin:0 0 28px;padding:0;list-style:none}
.article-body ul li{padding:16px 18px 16px 54px;margin:0;border:1px solid #dce7f5;border-radius:18px;background:linear-gradient(180deg,#ffffff,#f8fbff);font-size:16px;line-height:1.75}
.article-body ul li::before{left:18px;top:21px;width:20px;height:20px;background:linear-gradient(135deg,#1565d8,#0b4ca5)}
.article-inline-media{margin:32px 0}
.article-inline-media img{display:block;width:100%;height:auto;border-radius:18px;box-shadow:0 16px 42px rgba(4,30,66,.12)}
.article-inline-media figcaption{margin-top:10px;color:#66778c;font-size:13px;line-height:1.5;text-align:center}
.article-product-cta{margin-top:42px;align-items:flex-start;padding:28px 142px 28px 28px}
.article-product-cta-copy{width:100%}
.article-product-cta h3{margin:0;color:#fff;font:700 20px/1.35 var(--disp)}
.article-body .article-product-cta p{margin:5px 0 0;color:#cfe0fa;font:400 14px/1.5 var(--body)}
.article-product-cta-actions{display:flex;gap:10px;flex-wrap:wrap}
.article-product-cta .btn-ghost{border-color:rgba(255,255,255,.4);color:#fff;background:transparent}
.article-product-cta .btn-ghost:hover{border-color:#fff;background:rgba(255,255,255,.12)}

.article-more{padding:32px 0 82px;background:#fbfaf7;border-top:1px solid #dce5ef}
.article-more>.wrap{max-width:1040px}
.article-sibling-nav{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;padding:32px 0 48px;border-bottom:1px solid #dce5ef}
.article-sibling{display:flex;min-height:92px;padding:18px 20px;flex-direction:column;justify-content:center;gap:10px;border:1px solid #d4dfec;border-radius:14px;background:#fff;color:inherit;text-decoration:none;box-shadow:0 8px 24px rgba(4,30,66,.035);transition:border-color .2s,box-shadow .2s,transform .2s}
.article-sibling:hover{transform:translateY(-2px);border-color:#96bce9;box-shadow:0 12px 28px rgba(4,30,66,.08)}
.article-sibling span{display:flex;align-items:center;gap:7px;color:#7286a0;font:700 10px/1 var(--mono);letter-spacing:.11em;text-transform:uppercase}
.article-sibling i{color:#1565d8;font-size:15px;font-style:normal;line-height:1}
.article-sibling strong{display:-webkit-box;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:2;color:#071f46;font:750 15px/1.45 var(--disp)}
.article-next{grid-column:2;text-align:right}
.article-next span{justify-content:flex-end}
.article-related{padding-top:34px}
.article-related-head{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-bottom:17px}
.article-related-head h2{margin:0;color:#071f46;font:800 20px/1.25 var(--disp);letter-spacing:-.02em}
.article-related-grid{display:flex;flex-wrap:nowrap;gap:14px;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none;min-width:0;width:100%}
.article-related-grid>.article-related-card{flex:0 0 calc((100% - 28px)/3);scroll-snap-align:start}
@media(max-width:900px){.article-related-grid>.article-related-card{flex-basis:calc((100% - 14px)/2)}}
@media(max-width:560px){.article-related-grid>.article-related-card{flex-basis:86%}}
.article-related-card{display:flex;min-width:0;min-height:132px;padding:20px;flex-direction:column;border:1px solid #d4dfec;border-radius:14px;background:#fff;color:inherit;text-decoration:none;box-shadow:0 8px 24px rgba(4,30,66,.03);transition:border-color .2s,box-shadow .2s,transform .2s}
.article-related-card:hover{transform:translateY(-3px);border-color:#96bce9;box-shadow:0 13px 30px rgba(4,30,66,.08)}
.article-related-card>span{margin-bottom:10px;color:#1565d8;font:750 10px/1 var(--mono);letter-spacing:.12em;text-transform:none}
.article-related-card h3{display:-webkit-box;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:2;margin:0 0 15px;color:#071f46;font:750 16px/1.45 var(--disp);letter-spacing:-.01em}
.article-related-card small{margin-top:auto;color:#71839a;font:600 12px/1.3 var(--mono)}
.article-more-head{display:flex;align-items:end;justify-content:space-between;gap:18px;margin-bottom:24px}
.article-more-head h3{margin:0;color:var(--navy);font:850 30px/1.15 var(--disp);letter-spacing:-.035em;text-transform:none}
.article-more-grid{grid-template-columns:repeat(3,minmax(0,1fr))}
.article-more-card{display:flex;overflow:hidden;height:100%;padding:0;flex-direction:column;text-decoration:none}
.article-more-media{position:relative;display:block;overflow:hidden;width:100%;height:190px;background:linear-gradient(135deg,#dceaff,#f3f7fc)}
.article-more-media img{display:block;width:100%;height:100%;object-fit:cover;transition:transform .35s ease}
.article-more-card:hover .article-more-media img{transform:scale(1.045)}
.article-more-arrow{position:absolute;right:13px;bottom:13px;display:grid;place-items:center;width:35px;height:35px;border:1px solid rgba(255,255,255,.7);border-radius:50%;background:rgba(5,40,85,.82);color:#fff;font-size:16px;box-shadow:0 8px 20px rgba(3,23,53,.22);transition:background .2s,transform .2s}
.article-more-card:hover .article-more-arrow{background:var(--blue);transform:translateY(-2px)}
.article-more-content{display:flex;flex:1;padding:21px 22px 24px;flex-direction:column;align-items:flex-start}
.article-more-card .k{display:inline-block;margin-bottom:10px;font-weight:750}
.article-more-card h4{margin:0 0 9px;color:var(--navy);font:850 18px/1.35 var(--disp);letter-spacing:-.015em;text-align:left}
.article-more-card p{display:-webkit-box;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:4;text-align:left}

@media(max-width:1100px){
  .article-grid{grid-template-columns:1fr}
  .article-side-card,.article-sidebar .article-side-card + .article-side-card{position:static}
}
@media(max-width:900px){
  .article-hero .wrap,.article-more-grid,.article-related-grid{grid-template-columns:1fr}
  .article-hero{padding:46px 0 42px}
  .article-cover{min-height:260px}
}
@media(max-width:640px){
  .bp-bar .wrap{align-items:flex-start;flex-direction:column}
  .article-hero h1{font-size:clamp(30px,9vw,42px)}
  .article-hero .lede{font-size:16px}
  .article-grid{padding:26px 16px 52px}
  .article-side-card{padding:18px}
  .article-body p{font-size:16px;line-height:1.82}
  .article-body h2{font-size:clamp(24px,7vw,32px)}
  .article-body ul li{padding:14px 14px 14px 48px;font-size:15px}
  .article-product-cta{padding:24px 18px}
  .article-product-cta-actions{width:100%}
  .article-product-cta-actions .btn{flex:1 1 180px;text-align:center}
  .article-product-cta .pp-cta-buddha-link{margin:4px auto 0}
  .article-more-head{align-items:flex-start;flex-direction:column}
  .article-more{padding:18px 0 58px}
  .article-sibling-nav{grid-template-columns:1fr;padding:24px 0 36px}
  .article-next{grid-column:auto}
  .article-sibling{min-height:84px;padding:16px}
  .article-related{padding-top:28px}
  .article-related-head{align-items:flex-start;flex-direction:column}
}

/* SiteLock-only hero: reference copy with the existing XcellHost artwork. */
#ppage .sitelock-hero{min-height:590px;padding:50px 0 46px}
#ppage .sitelock-copy{position:relative;z-index:4;width:min(58%,690px)}
#ppage .sitelock-copy .pp-crumb{margin-bottom:17px}
#ppage .sitelock-eyebrow{display:inline-flex;align-items:center;gap:8px;margin-bottom:15px;padding:7px 14px;border:1px solid rgba(255,255,255,.18);border-radius:999px;background:rgba(255,255,255,.08);color:#bcd4ff;font:600 11px/1 var(--mono);letter-spacing:.12em;text-transform:uppercase}
#ppage .sitelock-eyebrow .dot{width:7px;height:7px;border-radius:50%;background:#5fe08d;box-shadow:0 0 0 5px rgba(95,224,141,.12)}
#ppage .sitelock-copy h1{margin-bottom:12px;font-size:clamp(27px,3.1vw,39px)}
#ppage .sitelock-lead{margin:0 0 4px;color:#eaf2ff;font:600 18px/1.5 var(--body)}
#ppage .sitelock-sub{max-width:590px;margin:0 0 12px;color:#c9d8f2;font:400 15.5px/1.55 var(--body)}
#ppage .sitelock-tech{margin:0 0 15px;color:#7fb0ff;font:700 18px/1.4 var(--disp)}
#ppage .sitelock-checks{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px 20px;max-width:590px;margin-bottom:20px}
#ppage .sitelock-check{display:flex;align-items:center;gap:9px;min-width:0;color:#eaf2ff;font:500 13.5px/1.35 var(--body)}
#ppage .sitelock-check span{display:grid;place-items:center;flex:0 0 21px;width:21px;height:21px;border-radius:50%;background:#1565d8;color:#fff;font:800 12px/1 var(--body)}
#ppage .sitelock-ctas{display:flex;align-items:center;gap:12px;flex-wrap:nowrap;width:max-content}
#ppage .sitelock-ctas .btn{display:inline-flex;align-items:center;justify-content:center;flex:0 0 auto;min-height:46px;margin:0;padding:11px 17px;white-space:nowrap}
#ppage .pph-sitelock-brand{top:auto;right:5%;bottom:22px;width:40%;height:82px;justify-content:center;overflow:visible;opacity:1;mask-image:none}
#ppage .pph-sitelock-logo{display:block;width:min(230px,72%);max-height:72px;object-fit:contain;border-radius:7px;filter:drop-shadow(0 8px 18px rgba(0,0,0,.32))}

@media(max-width:900px){
  #ppage .sitelock-hero{min-height:0;padding:38px 0 42px}
  #ppage .sitelock-copy{width:100%}
  #ppage .sitelock-copy h1{white-space:normal}
  #ppage .pph-sitelock-brand{display:none}
}
@media(max-width:620px){
  #ppage .sitelock-eyebrow{font-size:9px;letter-spacing:.08em}
  #ppage .sitelock-copy h1{display:block;font-size:clamp(24px,8vw,31px)}
  #ppage .sitelock-copy h1 .pp-title-name{margin-left:.18em}
  #ppage .pp-hero.sitelock-hero::before{opacity:.26}
  #ppage .sitelock-lead{font-size:16px}
  #ppage .sitelock-sub{font-size:14px}
  #ppage .sitelock-tech{font-size:16px}
  #ppage .sitelock-checks{grid-template-columns:1fr}
  #ppage .sitelock-ctas{display:flex;width:100%;overflow-x:auto;padding-bottom:8px}
  #ppage .sitelock-ctas .btn{width:auto;min-height:46px}
}

/* ==========================================================================
   UNIFORM NIGHT-MODE CONTENT SURFACES
   Every routed page follows the same near-black section + charcoal card
   hierarchy. Important declarations are intentional: several legacy pages
   ship lazy component styles with literal white backgrounds after this file.
   The permanent site header is outside router-outlet and remains white.
   ========================================================================== */
html.dark-mode.dark-mode.dark-mode router-outlet + * :where(section) {
  background-color: var(--theme-page) !important;
  border-color: var(--theme-border) !important;
}

html.dark-mode.dark-mode.dark-mode router-outlet + * :is(
  article,
  details,
  .card,
  .dir-cat,
  .faq2,
  .tcard,
  .ppl,
  .ppl2,
  .dpp,
  .dpt,
  .sp-c,
  .sp-ct,
  .spp,
  .pp-feat,
  .pp-addon,
  .pp-badge,
  .pp-tablewrap,
  .tally-plan-card,
  .cloud-backup-plan-card,
  .smb-price-plan,
  [class$="-card"]:not(.card-brand),
  [class*="-card "]:not(.card-brand),
  [class$="-panel"],
  [class*="-panel "],
  [class$="-tile"],
  [class$="-box"]
) {
  background: var(--theme-surface) !important;
  border-color: var(--theme-border) !important;
  color: var(--theme-text) !important;
  box-shadow: 0 8px 24px rgba(0, 0, 0, .28) !important;
}

/* Pricing cards contain nested light columns, so convert those as surfaces too. */
html.dark-mode.dark-mode.dark-mode router-outlet + * :is(
  .tally-plan-main,
  .cloud-backup-plan-main,
  .smb-plan-main,
  .tally-plan-specs,
  .tally-plan-specs > div,
  .smb-plan-features li,
  .smb-appliance-price,
  .cdr-plan-purchase,
  .cdr-quantity,
  .edr-plan-purchase,
  .edr-quantity
) {
  background: var(--theme-surface-raised) !important;
  border-color: var(--theme-border) !important;
  color: var(--theme-text) !important;
}

html.dark-mode.dark-mode.dark-mode router-outlet + * :is(
  article,
  details,
  .card,
  .dir-cat,
  .faq2,
  .tcard,
  .ppl,
  .ppl2,
  .dpp,
  .dpt,
  .sp-c,
  .sp-ct,
  .spp,
  .pp-feat,
  .pp-addon,
  .pp-badge,
  .pp-tablewrap,
  .tally-plan-card,
  .cloud-backup-plan-card,
  .smb-price-plan,
  [class$="-card"]:not(.card-brand),
  [class*="-card "]:not(.card-brand),
  [class$="-panel"],
  [class*="-panel "],
  [class$="-tile"],
  [class$="-box"]
) :is(h1, h2, h3, h4, h5, h6, strong, b, summary, .faq2-q) {
  color: var(--theme-text) !important;
}

html.dark-mode.dark-mode.dark-mode router-outlet + * :is(
  article,
  details,
  .card,
  .dir-cat,
  .faq2,
  .tcard,
  .ppl,
  .ppl2,
  .dpp,
  .dpt,
  .sp-c,
  .sp-ct,
  .spp,
  .pp-feat,
  .pp-addon,
  .pp-badge,
  .pp-tablewrap,
  .tally-plan-card,
  .cloud-backup-plan-card,
  .smb-price-plan,
  [class$="-card"]:not(.card-brand),
  [class*="-card "]:not(.card-brand),
  [class$="-panel"],
  [class*="-panel "],
  [class$="-tile"],
  [class$="-box"]
) :is(p, li, small, label, dt, dd, td, th) {
  color: var(--theme-muted) !important;
}

html.dark-mode.dark-mode.dark-mode router-outlet + * :is(
  .tally-plan-name b,
  .tally-plan-main > strong,
  .tally-plan-specs dd,
  .smb-plan-name b,
  .smb-selected-price,
  .smb-price-option strong,
  .faq2-q,
  .tcard .tname
) {
  color: var(--theme-text) !important;
}

html.dark-mode.dark-mode.dark-mode router-outlet + * :is(
  .tally-plan-main > p,
  .tally-plan-main > small,
  .tally-plan-specs dt,
  .smb-starting,
  .smb-gst,
  .smb-plan-features li,
  .tcard .trole,
  .tcard p,
  .faq2-a p
) {
  color: var(--theme-muted) !important;
}

/* Keep functional accents recognizable against the uniform cards. */
html.dark-mode router-outlet + * :is(.eyebrow, [class*="kicker"], [class*="section-label"]) {
  color: #69a3ff !important;
}
html.dark-mode router-outlet + * :is(.tstars, .testimonial-stars, [class*="stars"]) {
  color: var(--orange) !important;
}
html.dark-mode router-outlet + * .card-brand,
html.dark-mode router-outlet + * .card-brand * {
  background-color: #fff !important;
  color: inherit !important;
}

/* The Global DC map is a visualization, not a content card. */
html.dark-mode.dark-mode.dark-mode router-outlet + * .dc-tab-panel {
  background: transparent !important;
  border-color: transparent !important;
  box-shadow: none !important;
}

